import{_ as e,o as r,c as t,a as i}from"./chunks/framework.fmIt2z2h.js";const o="/xi-kari-skill/handbook/images/mars-climate-orbiter.svg",_=JSON.parse('{"title":"火星气候轨道器：文件传到了，数值的含义却没有对上","description":"","frontmatter":{"slug":"mars-climate-orbiter","title":"火星气候轨道器：文件传到了，数值的含义却没有对上","kind":"真实案例","source_type":"官方事故调查报告","concepts":["representation-loss","local-and-whole-chain"]},"headers":[],"relativePath":"cases/mars-climate-orbiter.md","filePath":"cases/mars-climate-orbiter.md"}'),s={name:"cases/mars-climate-orbiter.md"};function l(n,a,c,h,p,m){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="火星气候轨道器-文件传到了-数值的含义却没有对上" tabindex="-1">火星气候轨道器：文件传到了，数值的含义却没有对上 <a class="header-anchor" href="#火星气候轨道器-文件传到了-数值的含义却没有对上" aria-label="Permalink to &quot;火星气候轨道器：文件传到了，数值的含义却没有对上&quot;">​</a></h1><p>1999年9月23日，火星气候轨道器在抵达火星时失联。它原计划研究火星气候，并承担通信中继任务。NASA将这次任务列为失败，并将单位转换错误造成的导航偏差列为原因。<a href="https://science.nasa.gov/mission/mars-climate-orbiter/" target="_blank" rel="noreferrer">NASA任务资料</a></p><h2 id="事故报告确认了什么" tabindex="-1">事故报告确认了什么 <a class="header-anchor" href="#事故报告确认了什么" aria-label="Permalink to &quot;事故报告确认了什么&quot;">​</a></h2><p>调查报告指出，地面软件SM_FORCES输出的推进器冲量使用了磅力秒，接口规范要求的却是牛顿秒。导航软件按规定单位解释数据，因而将相关推力影响低估了约4.45倍。报告同时列出验证、沟通、人员与培训等促成因素。单位要求已经写在规范里，实际数据却没有遵守要求，既有检查也没有及时捕获这一问题。<a href="https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" target="_blank" rel="noreferrer">NASA第一阶段调查报告，第6—7、16—17页</a></p><figure class="concept-figure"><img src="'+o+'" alt="mars-climate-orbiter案例的关系图"><figcaption>根据本页官方资料绘制，保留图示的适用范围。</figcaption></figure><h2 id="从这里读懂一个区别" tabindex="-1">从这里读懂一个区别 <a class="header-anchor" href="#从这里读懂一个区别" aria-label="Permalink to &quot;从这里读懂一个区别&quot;">​</a></h2><p>这个案例可以帮助阅读《Xikari-条件结构与转化论》中“表示充分与实际执行正确分别检验”的区别。接收一个数值文件，能够确认传递发生，却还要核对它保留了什么含义、接受方采用了什么解释规则，以及这些规则是否符合本次任务。</p><p>原文在附录C.7用形式例子区分两类问题：必要区别在表示中已经丢失，和信息足够但实际规则用错。前者不能只靠换一条计算规则补回；后者也不必一律归咎于信息缺失。本案例的具体故障由NASA调查报告认定，原文提供的是阅读这种区别的提问方式：问题究竟发生在数据含义、映射关系、使用规则，还是后续执行？不能仅凭“接口有输出”就合并回答。<a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-7">阅读原文：附录C.7</a></p><h2 id="看图时保留什么" tabindex="-1">看图时保留什么 <a class="header-anchor" href="#看图时保留什么" aria-label="Permalink to &quot;看图时保留什么&quot;">​</a></h2><p>从推进器活动，到地面软件、数据文件和导航计算，每个节点都有对应量与单位。单位不是可忽略的文字标签；同一串数字进入不同解释规则，会改变计算结果。图中并列了“规范要求的单位”和“实际输出的单位”，接口处的差异也就显露出来。</p><p>同时，单个接口失配并不自动回答全部责任分配。原文将实际承接、成本承担、停止权与责任主体分开；谁写入文件、谁使用文件、谁负责验证，各自需要具体依据，不能从谁最可见直接得出谁承担全部责任。<a href="/xi-kari-skill/handbook/theory/part-02.html#section-2-8">阅读原文：§2.8与责任边界</a></p><p>本页依据事故调查材料帮助辨认接口、规则和结果的区别。它不由一个事故证明所有跨组织协作必然失败，也不把事后能够解释事故当成事前已经能够预测事故。</p><h2 id="对照概念与原文" tabindex="-1">对照概念与原文 <a class="header-anchor" href="#对照概念与原文" aria-label="Permalink to &quot;对照概念与原文&quot;">​</a></h2><ul><li><a href="./../concepts/responsibility.html">实际承接与责任依据</a></li><li><a href="./../concepts/chain.html">从局部作用到整条链</a></li></ul>',14)])])}const f=e(s,[["render",l]]);export{_ as __pageData,f as default};
